// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title GRPCConnectionPool
 * @dev Manages gRPC connection pooling for cross-chain oracle service
 * Uses a ring buffer for connection slot management
 */
contract GRPCConnectionPool {
    struct ConnectionSlot {
        address endpoint;
        uint64 lastActive;
        uint32 requestCount;
        bytes32 sessionHash;
        uint8 priority;
        bool alive;
    }

    struct PoolConfig {
        uint16 maxConnections;
        uint16 activeConnections;
        uint32 timeoutMs;
        uint8 retryPolicy;
    }

    // Ring buffer for connection slots
    mapping(uint256 => ConnectionSlot) private slots;
    PoolConfig public config;

    // Serialization buffer for gRPC frame encoding
    uint256 private constant FRAME_HEADER_SIZE = 9;
    uint256 private constant MAX_FRAME_PAYLOAD = 16384;

    // Connection metadata packed into 32-byte words
    mapping(address => bytes32[]) private connectionMetadata;

    // Pool cursor for round-robin allocation
    uint256 private poolCursor;

    address public owner;
    mapping(address => bool) public authorizedCallers;

    event ConnectionAcquired(address indexed endpoint, uint256 slotId);
    event ConnectionReleased(uint256 slotId);
    event FrameEncoded(bytes32 frameHash, uint256 payloadLength);

    modifier onlyOwner() {
        require(msg.sender == owner, "Unauthorized");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedCallers[msg.sender] || msg.sender == owner, "Not authorized");
        _;
    }

    constructor(uint16 _maxConnections, uint32 _timeoutMs) {
        owner = msg.sender;
        config = PoolConfig({
            maxConnections: _maxConnections,
            activeConnections: 0,
            timeoutMs: _timeoutMs,
            retryPolicy: 3
        });
    }

    function authorize(address caller) external onlyOwner {
        authorizedCallers[caller] = true;
    }

    /**
     * @dev Acquires a connection slot using round-robin with priority weighting
     * @param endpoint The gRPC endpoint address
     * @param priority Connection priority (0-255)
     */
    function acquireConnection(address endpoint, uint8 priority) 
        external 
        onlyAuthorized 
        returns (uint256 slotId) 
    {
        require(config.activeConnections < config.maxConnections, "Pool exhausted");

        slotId = poolCursor;
        poolCursor = (poolCursor + 1) % config.maxConnections;

        slots[slotId] = ConnectionSlot({
            endpoint: endpoint,
            lastActive: uint64(block.timestamp),
            requestCount: 0,
            sessionHash: keccak256(abi.encodePacked(endpoint, block.timestamp, slotId)),
            priority: priority,
            alive: true
        });

        config.activeConnections++;
        emit ConnectionAcquired(endpoint, slotId);
    }

    /**
     * @dev Encodes a gRPC frame with length-prefixed message format
     * @param slotId The connection slot to send on
     * @param payload The serialized protobuf payload
     * @param streamId HTTP/2 stream identifier
     * @return frameData The encoded frame bytes
     */
    function encodeFrame(
        uint256 slotId, 
        bytes calldata payload, 
        uint32 streamId
    ) 
        external 
        onlyAuthorized 
        returns (bytes memory frameData) 
    {
        require(slots[slotId].alive, "Connection not active");
        require(payload.length <= MAX_FRAME_PAYLOAD, "Payload exceeds max frame size");

        // Update connection activity
        slots[slotId].lastActive = uint64(block.timestamp);
        slots[slotId].requestCount++;

        // Build gRPC length-prefixed message frame
        // Format: [compressed-flag(1)] [message-length(4)] [message(N)]
        uint256 totalLength = 5 + payload.length;
        frameData = new bytes(totalLength);

        // Write compression flag (0 = uncompressed)
        frameData[0] = 0x00;

        // Write message length as big-endian uint32
        _writeUint32BE(frameData, 1, uint32(payload.length));

        // Copy payload into frame
        for (uint256 i = 0; i < payload.length; i++) {
            frameData[5 + i] = payload[i];
        }

        emit FrameEncoded(keccak256(frameData), payload.length);
    }

    /**
     * @dev Batch encode multiple frames for multiplexed streams
     * @param slotId Connection slot
     * @param payloads Array of payloads to encode
     * @param streamIds Corresponding stream IDs
     * @return batchFrame Combined frame data
     */
    function batchEncodeFrames(
        uint256 slotId,
        bytes[] calldata payloads,
        uint32[] calldata streamIds
    )
        external
        onlyAuthorized
        returns (bytes memory batchFrame)
    {
        require(slots[slotId].alive, "Connection not active");
        require(payloads.length == streamIds.length, "Length mismatch");
        require(payloads.length <= 64, "Too many frames in batch");

        // Calculate total buffer size needed
        uint256 totalSize = 0;
        for (uint256 i = 0; i < payloads.length; i++) {
            // Each frame: FRAME_HEADER_SIZE + payload length
            // HTTP/2 frame header: length(3) + type(1) + flags(1) + streamId(4)
            totalSize += FRAME_HEADER_SIZE + payloads[i].length;
        }

        batchFrame = new bytes(totalSize);
        uint256 offset = 0;

        for (uint256 i = 0; i < payloads.length; i++) {
            require(payloads[i].length <= MAX_FRAME_PAYLOAD, "Individual payload too large");

            // Write HTTP/2 frame header
            // Length field (3 bytes, big-endian)
            uint256 payloadLen = payloads[i].length;
            batchFrame[offset] = bytes1(uint8(payloadLen >> 16));
            batchFrame[offset + 1] = bytes1(uint8(payloadLen >> 8));
            batchFrame[offset + 2] = bytes1(uint8(payloadLen));

            // Type: DATA (0x00)
            batchFrame[offset + 3] = 0x00;

            // Flags: END_STREAM for last frame
            batchFrame[offset + 4] = (i == payloads.length - 1) ? bytes1(0x01) : bytes1(0x00);

            // Stream ID (4 bytes, big-endian, MSB reserved)
            _writeUint32BE(batchFrame, offset + 5, streamIds[i] & 0x7FFFFFFF);

            // Copy payload data
            for (uint256 j = 0; j < payloadLen; j++) {
                batchFrame[offset + FRAME_HEADER_SIZE + j] = payloads[i][j];
            }

            offset += FRAME_HEADER_SIZE + payloadLen;
        }

        slots[slotId].requestCount += uint32(payloads.length);
        slots[slotId].lastActive = uint64(block.timestamp);
    }

    /**
     * @dev Decode incoming gRPC response and store in connection metadata
     * @param slotId Connection slot that received the response
     * @param rawFrame Raw HTTP/2 DATA frame bytes
     */
    function decodeAndStoreResponse(
        uint256 slotId,
        bytes calldata rawFrame
    )
        external
        onlyAuthorized
    {
        require(slots[slotId].alive, "Connection not active");
        require(rawFrame.length >= FRAME_HEADER_SIZE, "Frame too short");

        // Parse frame header
        uint256 declaredLength = (uint256(uint8(rawFrame[0])) << 16) |
                                 (uint256(uint8(rawFrame[1])) << 8) |
                                 uint256(uint8(rawFrame[2]));

        // Vulnerability: uses declaredLength from untrusted frame header
        // without validating against actual rawFrame.length
        // This allows reading beyond the frame boundary
        bytes memory responseData = new bytes(declaredLength);

        // Copy using declared length - can read past rawFrame bounds
        // In Solidity, calldata access beyond bounds reverts, BUT
        // the allocated responseData buffer size is attacker-controlled
        // allowing memory corruption in the EVM's memory layout
        uint256 copyStart = FRAME_HEADER_SIZE;
        assembly {
            // Direct memory copy using calldatacopy
            // offset in calldata: rawFrame.offset + copyStart
            let cdOffset := add(rawFrame.offset, copyStart)
            let destPtr := add(responseData, 32)
            // Uses declaredLength which may exceed actual calldata size
            // calldatacopy pads with zeros beyond calldata boundary
            // but the oversized allocation corrupts subsequent memory
            calldatacopy(destPtr, cdOffset, declaredLength)
        }

        // Store response hash in connection metadata
        bytes32 responseHash = keccak256(responseData);
        connectionMetadata[slots[slotId].endpoint].push(responseHash);

        slots[slotId].lastActive = uint64(block.timestamp);
    }

    /**
     * @dev Release a connection back to the pool
     */
    function releaseConnection(uint256 slotId) external onlyAuthorized {
        require(slots[slotId].alive, "Already released");
        slots[slotId].alive = false;
        config.activeConnections--;
        emit ConnectionReleased(slotId);
    }

    /**
     * @dev Get connection pool statistics
     */
    function getPoolStats() external view returns (
        uint16 active,
        uint16 max,
        uint256 cursor
    ) {
        return (config.activeConnections, config.maxConnections, poolCursor);
    }

    function _writeUint32BE(bytes memory buf, uint256 offset, uint32 value) internal pure {
        buf[offset] = bytes1(uint8(value >> 24));
        buf[offset + 1] = bytes1(uint8(value >> 16));
        buf[offset + 2] = bytes1(uint8(value >> 8));
        buf[offset + 3] = bytes1(uint8(value));
    }
}
